# Bell-LaPadula protects confidentiality; Biba protects integrity. Same levels, opposite rules.
LEVELS = {'public': 0, 'internal': 1, 'confidential': 2, 'restricted': 3}

def blp(subject, obj, action):
    s, o = LEVELS[subject], LEVELS[obj]
    if action == 'read':
        return s >= o   # simple security property: no read up
    return s <= o       # *-property: no write down

def biba(subject, obj, action):
    s, o = LEVELS[subject], LEVELS[obj]
    if action == 'read':
        return s <= o   # simple integrity axiom: no read down
    return s >= o       # *-integrity axiom: no write up

tests = [
    ('confidential', 'restricted', 'read'),
    ('confidential', 'internal', 'read'),
    ('confidential', 'internal', 'write'),
    ('confidential', 'restricted', 'write'),
]
print(f"{'subject':<13}{'action':<7}{'object':<13}{'Bell-LaPadula':<15}Biba")
for subject, obj, action in tests:
    ok = lambda allowed: 'allow' if allowed else 'deny'
    print(f'{subject:<13}{action:<7}{obj:<13}{ok(blp(subject, obj, action)):<15}{ok(biba(subject, obj, action))}')
